<?php
$statsPage=$page==='admin-stats';
$matches=query('SELECT * FROM matches'.($statsPage?" WHERE status='Completed'":'').' ORDER BY match_date DESC,match_time DESC');
$default=$statsPage?($matches[0] ?? null):(next_match() ?? ($matches[0] ?? null));
$id=(int)($_GET['id'] ?? ($default['id'] ?? 0)); $m=$id?match_by_id($id):null;
?>
<form method="get" class="panel inline-form mb-4"><input type="hidden" name="page" value="<?= e($page) ?>"><label class="field flex-grow-1">Select match<select class="form-select" name="id"><?php foreach($matches as $row): ?><option value="<?= e($row['id']) ?>" <?= $id==$row['id']?'selected':'' ?>><?= e($row['match_date'].' · '.$row['opponent_name'].' · '.$row['status']) ?></option><?php endforeach; ?></select></label><button class="btn btn-dark">View match</button></form>
<?php if(!$m): ?><div class="panel empty">Chưa có trận phù hợp. Tạo trận đấu trước.</div><?php elseif($statsPage && $m['status']!=='Completed'): ?><div class="alert alert-warning">Trận này chưa Completed. Hãy cập nhật kết quả trước.</div><?php else: ?>
<section class="panel"><h2><?= e(match_title($m)) ?></h2><p class="muted"><?= e($m['match_date'].' · '.MATCH_VENUE_NAME) ?> · <strong><?= e(score($m)) ?></strong></p>
<?php if($statsPage): $existing=array_column(match_stats($id),null,'player_id'); $total=array_sum(array_column($existing,'goals')); if($total!=(int)$m['our_score']): ?><div class="alert alert-warning">⚠ Goal statistics do not match match score. Khai báo: <?= $total ?> / Kết quả đội: <?= e($m['our_score']) ?>.</div><?php endif; ?><p class="muted">Admin có thể sửa mọi thống kê. Xác nhận cầu thủ đã thi đấu tại Attendance để tính Matches played.</p><?php endif; ?>
<div class="data-rows"><?php $allPlayers=query("SELECT p.*,COALESCE(a.status,'NO_RESPONSE') AS response FROM players p LEFT JOIN match_availability a ON a.player_id=p.id AND a.match_id=? WHERE p.is_active=1 OR ?='Completed' ORDER BY p.jersey_number",[$id,$m['status']]); foreach($allPlayers as $p): $s=$existing[$p['id']] ?? null; ?><form method="post" class="data-row"><?= csrf() ?><input type="hidden" name="action" value="<?= $statsPage?'stats':'attendance' ?>"><input type="hidden" name="match_id" value="<?= $id ?>"><input type="hidden" name="player_id" value="<?= e($p['id']) ?>"><div class="data-player"><strong>#<?= e($p['jersey_number']) ?> <?= e($p['full_name']) ?></strong><small><?= e($p['response']) ?><?= !$p['is_active']?' · Inactive':'' ?></small><?php if($statsPage && $s): ?><small>Updated <?= e($s['updated_at']) ?> · <?= e($s['editor']) ?></small><?php endif; ?></div><?php if($statsPage): field('Goals','goals',$s['goals'] ?? 0,'number',true,'min="0" max="999"'); field('Assists','assists',$s['assists'] ?? 0,'number',true,'min="0" max="999"'); else: select_field('Availability','status',['YES'=>'YES — Playing','NO'=>'NO — Not playing','MAYBE'=>'MAYBE','NO_RESPONSE'=>'Waiting for response'],$p['response']); endif; ?><button class="btn btn-dark">Save</button></form><?php endforeach; ?></div></section><?php endif; ?>
